function SelectServerDialog:Awake()
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    self.ownerServers = userComponent.userInfo.servers
    SetButtonAction(self.Buttton1 , function ()
        
        local servers =   userComponent.userInfo.servers
        local lastLoginServerId = userComponent.userInfo.lastLoginServerId
        if checkInt(lastLoginServerId) <= 0 then
            GameUtils.Toast(localize('没有个人角色信息'))
            return
        end
        self.isMy = true
        self:SwitchMyOrAll(true)
        self:RefreshUI()
    end)
    SetButtonAction(self.Buttton2 , function ()
        self.isMy = false
        self:SwitchMyOrAll(false)
        self:RefreshUI()
    end)
    SetButtonAction(self.BtnClose , function ()
        UIModule.CloseDialog(self.controller)
    end)
end

function SelectServerDialog:SwitchMyOrAll(isMy)
    KTool.SetActive(self.MyServer , isMy)
    KTool.SetActive(self.AllServer , not isMy)
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    local servers = userComponent.userInfo.servers or {}
    if #servers == 0 then
        KTool.SetActive(self.Buttton1 , false)
        self.Buttton2.transform:SetLocalXYZ(-1.259995 , 262.5 , 0 ) 
    end
    local ImgSelectArrow =  self.Buttton1.transform:Find("ImgSelectArrow")
    if isNotNull(ImgSelectArrow) then
        KTool.SetActive(ImgSelectArrow , isMy)
    end
    local myStatus = isMy and 2 or 1
    local ImgIcon = self.Buttton1.transform:Find("ImgIcon")
    if isNotNull(ImgIcon) then
        local UISwitchImage =  KTool.GetComponent(ImgIcon.gameObject ,typeof(CS.Game.Native.Common.UISwitchImage))
        UISwitchImage.Status = myStatus
    end

    local BtnBg =  self.Buttton1.transform:Find("BtnBg")
    if isNotNull(BtnBg) then
        local UISwitchImage =  KTool.GetComponent(BtnBg.gameObject ,typeof(CS.Game.Native.Common.UISwitchImage))
        UISwitchImage.Status = myStatus
    end

    local TxtName =  self.Buttton1.transform:Find("TxtName")
    if isNotNull(TxtName) then
        local UISwitchText =  KTool.GetComponent(TxtName.gameObject ,typeof(CS.Game.Native.Common.UISwitchText))
        UISwitchText.Status = myStatus
    end

    local allStatus = isMy and 1 or 2
    local ImgSelectArrow =  self.Buttton2.transform:Find("ImgSelectArrow")
    if isNotNull(ImgSelectArrow) then
        KTool.SetActive(ImgSelectArrow , not isMy)
    end

    local ImgIcon =  self.Buttton2.transform:Find("ImgIcon")
    if isNotNull(ImgIcon) then
        local UISwitchImage =  KTool.GetComponent(ImgIcon.gameObject ,typeof(CS.Game.Native.Common.UISwitchImage))
        UISwitchImage.Status = allStatus
    end

    local BtnBg =  self.Buttton2.transform:Find("BtnBg")
    if isNotNull(BtnBg) then
        local UISwitchImage =  KTool.GetComponent(BtnBg.gameObject ,typeof(CS.Game.Native.Common.UISwitchImage))
        UISwitchImage.Status = allStatus
    end
    local TxtName =  self.Buttton2.transform:Find("TxtName")
    if isNotNull(TxtName) then
        local UISwitchText =  KTool.GetComponent(TxtName.gameObject ,typeof(CS.Game.Native.Common.UISwitchText))
        UISwitchText.Status = allStatus
    end
    
end

function SelectServerDialog:RefreshUI()
    if self.isMy then
        self:RefreshMyUI()
    else 
        if self.serverList then
            self:RefreshAllUI()
        else 
            GameUtils.Request(Interfaces.UserGetServerList, {}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                userComponent:Initial({serverList = response.data.serverList})
                self.serverList = clone(userComponent.userInfo.serverList) 
                self:RefreshAllUI()
            end)    
        end
            
    end
end

