function SelectServerDialog:SelectServerId(id)
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent) 
    userComponent:Initial({cuurentServerId = id  , serverId = id } )
    if checkNumber(id) == 999 then
        PlayerPrefsUtility.SetEncryptedString("LOCAL_SERVER_ID", tostring(id))
        PlayerPrefsUtility.Save()
    else
        PlayerPrefsUtility.SetEncryptedString("LOCAL_SERVER_ID", "0")
        PlayerPrefsUtility.Save()
    end
    UIModule.BackDialog()
end

function SelectServerDialog:RefreshAllUI()
    if not self.AllServer.IsListViewInit then
        self.AllServer:InitGridView(#self.serverList, Bind(self, self.OnGetItemByIndex))
    else 
        GameUtils.ReloadData(self.AllServer, #self.serverList)    
    end  
end

function SelectServerDialog:RefreshOwnerUI()
    if not self.AllServer.IsListViewInit then
        self.ScrollRectContent:InitGridView(#self.ownerServers, Bind(self, self.OnOwnerGetItemByIndex))
    else 
        GameUtils.ReloadData(self.ScrollRectContent, #self.ownerServers)    
    end  
end

function SelectServerDialog:OnOwnerGetItemByIndex(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")   
    ---@type SelectServerNode
    local nodeEnv = CfUtils.GetLuaScr(cell, SelectServerNodeStr)
    if nodeEnv then
        nodeEnv:SetCallBack(Bind(self,self.SelectServerId))
        nodeEnv:UpdateUI(self.ownerServers[listIndex+1])
    end
    return cell
end
function SelectServerDialog:OnGetItemByIndex(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")   
    ---@type SelectServerNode
    local nodeEnv = CfUtils.GetLuaScr(cell, SelectServerNodeStr)
    if nodeEnv then
        nodeEnv:SetCallBack(Bind(self,self.SelectServerId))
        nodeEnv:UpdateUI(self.serverList[listIndex+1])
    end
    return cell
end

function SelectServerDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function ()
             ---@type UserComponent
            local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
            local servers =   userComponent.userInfo.servers
            local lastLoginServerId = userComponent.userInfo.lastLoginServerId
            if checkInt(lastLoginServerId) <= 0  then
                self.isMy = false
                self:SwitchMyOrAll(false) 
            end
            self:RefreshUI()   
        end)
    end))
    return coWait
end


